  choices = $EXPL$["Sign the client''s tax returns on their behalf without any additional authorization or designation","Access the client''s bank records without obtaining the client''s separate additional written consent","Override IRS determinations without pursuing any further appeal through the administrative process","Represent the client before all offices of the IRS for the specific matters listed on the form"]$EXPL$::jsonb,
